<nav class="customer-nav" aria-label="Navigasi utama"><?php foreach([['dashboard','view-dashboard-outline','Beranda'],['service-new','plus','Servis baru'],['invoices','receipt-text-outline','Invoice']] as [$route,$icon,$label]): ?><a href="<?=e(url($route))?>" class="<?=$active===$route?'active':''?>" <?=$active===$route?'aria-current="page"':''?>><?=mdi($icon)?><span><?=e($label)?></span></a><?php endforeach; ?></nav>
<?php else: ?>
<aside class="sidebar" id="navigation"><a class="brand brand-with-logo" href="<?=e(url())?>"><?php if($b['logo']): ?><img src="<?=e($b['logo'])?>" alt="<?=e($b['name'])?>"><?php else: ?><?=e($b['short_name'])?><?php endif; ?></a><nav aria-label="Navigasi utama">
<?php foreach([['dashboard','view-dashboard-outline','Ringkasan'],['orders','clipboard-text-outline','Servis'],['invoices','receipt-text-outline','Invoice'],['customers','account-group-outline','Konsumen'],['parts','package-variant-closed','Sparepart'],['account','cog-outline','Akun']] as [$route,$icon,$label]): $selected=$active===$route || ($route==='orders' && in_array($active,['order','service-edit','success','service-new'])); ?>
