<div class="profile"><span class="avatar">A</span><div><strong>Admin</strong><small><?=e($user['phone'])?></small></div><form method="post" action="<?=e(url('logout'))?>"><?=csrf()?><button class="logout" aria-label="Keluar" title="Keluar"><?=mdi('logout-variant')?></button></form></div></aside>
<?php endif; ?>
<div class="workspace"><?php if(!$isCustomer): ?><header class="topbar"><div><button type="button" class="menu-toggle" aria-label="Buka navigasi" aria-expanded="false" aria-controls="navigation"><?=mdi('menu')?></button><span><?=e($title)?></span></div><span class="top-date"><?=e(date('d M Y'))?> · WIB</span></header><?php endif; ?><main id="main">
<?php else: ?><main class="auth-layout"><?php endif; ?>
